console.log(dsu.connected(0, 2));  // true
console.log(dsu.union(0, 2));      // false (already connected)
console.log(dsu.union(3, 4));      // true
console.log(dsu.componentCount);   // 4  ({0,1,2}, {3,4}, {5})
console.log(dsu.connected(2, 3));  // false
