function findKth(fen, k) {                 // 1-indexed k
  let pos = 0;
  let remaining = k;
  for (let step = highestPowerOfTwo(fenSize(fen)); step > 0; step >>= 1) {
    if (pos + step <= fenSize(fen) && fen.tree(pos + step) < remaining) {
