// Sparse table for static range minimum.
function sparseTableMin(arr) {
  const n = arr.length, log = new Array(n + 1).fill(0);
  for (let i = 2; i <= n; i++) log[i] = log[i >> 1] + 1;
  const K = log[n] + 1;
  const st = Array.from({ length: K }, () => new Array(n));
  st[0] = arr.slice();
  for (let k = 1; k < K; k++)
    for (let i = 0; i + (1 << k) <= n; i++)
      st[k][i] = Math.min(st[k-1][i], st[k-1][i + (1 << (k-1))]);
  return {
    query(l, r) {
      const k = log[r - l + 1];
      return Math.min(st[k][l], st[k][r - (1 << k) + 1]);
    },
    buildTime: 'O(n log n)', queryTime: 'O(1)' };
