// Bloom filter with k independent hash functions from one base hash (Kirsch-Mitzenmacher).
class BloomFilter {
  #bits; #size; #k; #inserted = 0;
  constructor(expectedItems, falsePositiveRate = 0.01) {
    if (expectedItems <= 0) throw new RangeError('expectedItems must be positive');
    if (falsePositiveRate <= 0 || falsePositiveRate >= 1) throw new RangeError('fpp must be in (0,1)');
    this.#size = Math.ceil(-expectedItems * Math.log(falsePositiveRate) / (Math.log(2) ** 2));
    this.#k = Math.max(1, Math.round((this.#size / expectedItems) * Math.log(2)));
    this.#bits = new Uint8Array(Math.ceil(this.#size / 8));
  }
  get bitCount() { return this.#size; }
  get hashCount() { return this.#k; }
  get falsePositiveRate() { const r = this.#k * this.#inserted / this.#size; return (1 - Math.exp(-r)) ** this.#k; }
  #baseHash(str) {
    // FNV-1a 64-bit-ish via two 32-bit passes.
    let h1 = 0x811c9dc5, h2 = 0x01000193;
    for (let i = 0; i < str.length; i++) {
      const c = str.charCodeAt(i);
      h1 = Math.imul(h1 ^ c, 0x01000193);
      h2 = Math.imul(h2 ^ (c + i), 0x85ebca6b);
    }
    return [h1 >>> 0, h2 >>> 0];
  }
  #positions(str) {
    const [h1, h2] = this.#baseHash(str);
    for (let i = 0; i < this.#k; i++) {
      const combined = (Math.imul(h1, i + 1) + Math.imul(h2, 0x9e3779b1) * (i + 1)) >>> 0;
      yield combined % this.#size;
    }
  }
  add(str) {
    for (const pos of this.#positions(str)) {
      const byte = pos >> 3, bit = pos & 7;
      const before = this.#bits[byte];
      this.#bits[byte] = before | (1 << bit);
      if (!(before & (1 << bit))) this.#inserted++;
    }
    return this;
  }
  has(str) {
    for (const pos of this.#positions(str)) if (!(this.#bits[pos >> 3] & (1 << (pos & 7)))) return false;
    return true;
  }
  // Exact check for callers that need to be sure.
  mightContain(str) { return this.has(str); }
}
const bf = new BloomFilter(1000, 0.01);
console.log(bf.bitCount, bf.hashCount);   // ~9585 bits, ~7 hashes
for (let i = 0; i < 1000; i++) bf.add('item' + i);
let fp = 0;
for (let i = 1000; i < 11000; i++) if (bf.has('item' + i)) fp++;
console.log('false positives:', fp, '/ 10000  (~1%)');
