class CountingBloomFilter {
  #counters; #size; #k; #cap;
  constructor(expectedItems, fpp = 0.01, counterBits = 4) {
    this.#size = Math.ceil(-expectedItems * Math.log(fpp) / (Math.log(2) ** 2));
    this.#k = Math.max(1, Math.round((this.#size / expectedItems) * Math.log(2)));
    this.#cap = 2 ** counterBits - 1;
    this.#counters = new Uint8Array(Math.ceil(this.#size / counterBits * 8));  // packed-ish; simple version below
    this.#counters = new Uint8Array(this.#size);   // 1 byte per slot for clarity
  }
  #positions(str) {
    let h = 0x811c9dc5;
    for (let i = 0; i < str.length; i++) h = Math.imul(h ^ str.charCodeAt(i), 0x01000193);
    let h2 = 0x9e3779b1;
    for (let i = 0; i < str.length; i++) h2 = Math.imul(h2 ^ str.charCodeAt(i), 0x85ebca6b);
    h >>>= 0; h2 >>>= 0;
    for (let i = 0; i < this.#k; i++) yield ((Math.imul(h, i+1) + Math.imul(h2, i+1)) >>> 0) % this.#size;
  }
  add(str) { for (const p of this.#positions(str)) if (this.#counters[p] < this.#cap) this.#counters[p]++; return this; }
  remove(str) { for (const p of this.#positions(str)) if (this.#counters[p] > 0) this.#counters[p]--; return this; }
  has(str) { for (const p of this.#positions(str)) if (this.#counters[p] === 0) return false; return true; }
}
