function shortestBinaryPath(grid, start, goal) {
  const R = grid.length, C = grid[0].length;
  if (!grid[start[0]]?.[start[1]] || !grid[goal[0]]?.[goal[1]]) return -1;
  const seen = Array.from({ length: R }, () => new Array(C).fill(false));
  const dirs = [[-1,0],[1,0],[0,-1],[0,1]];
  seen[start[0]][start[1]] = true;
  let level = 0, frontier = [start];
  while (frontier.length) {
    const next = [];
    for (const [r, c] of frontier) {
      if (r === goal[0] && c === goal[1]) return level;
      for (const [dr, dc] of dirs) {
        const nr = r + dr, nc = c + dc;
        if (nr < 0 || nr >= R || nc < 0 || nc >= C) continue;
        if (grid[nr][nc] === '1' || seen[nr][nc]) continue;
        seen[nr][nc] = true;
        next.push([nr, nc]);
      }
    }
    frontier = next;
    level++;
  }
  return -1;
}
