function dijkstra(graph, source) {
  const dist = new Map(), prev = new Map(), settled = new Set();
  for (const v of graph.keys()) dist.set(v, Infinity);
  dist.set(source, 0);
  const heap = new Heap((a, b) => a[0] - b[0]);          // (dist, vertex)
  heap.push([0, source]);
  while (heap.size) {
    const [d, u] = heap.pop();
    if (settled.has(u)) continue;
    settled.add(u);
    for (const [v, w] of graph.get(u) ?? []) {
      const nd = d + w;
      if (nd < dist.get(v)) { dist.set(v, nd); prev.set(v, u); heap.push([nd, v]); }
    }
  }
  return { dist, prev };
}
