function eulerianPath(V, adj) {                // adj: array of neighbor arrays
  const used = new Set(), path = [];
  // Key detail: track used edges by (u,v) pair to avoid duplicates in undirected graphs.
  const iter = new Array(V).fill(0);
  const stack = [0];
  const edgeUsed = new Set();
  while (stack.length) {
    const u = stack[stack.length - 1];
    while (iter[u] < adj[u].length && edgeUsed.has(`${u}-${adj[u][iter[u]]}`)) iter[u]++;
    if (iter[u] === adj[u].length) path.push(stack.pop());
    else {
      const v = adj[u][iter[u]++];
      edgeUsed.add(`${u}-${v}`); edgeUsed.add(`${v}-${u}`);
      stack.push(v);
    }
  }
  return path.reverse();
}
