function bellmanFord(V, edges, source) {
  const dist = new Array(V).fill(Infinity);
  dist[source] = 0;
  for (let i = 0; i < V - 1; i++) {
    let changed = false;
    for (const [u, v, w] of edges) {
      if (dist[u] !== Infinity && dist[u] + w < dist[v]) { dist[v] = dist[u] + w; changed = true; }
    }
    if (!changed) break;                      // early termination
  }
  // Negative cycle check.
  let negCycle = false;
  for (const [u, v, w] of edges) if (dist[u] !== Infinity && dist[u] + w < dist[v]) negCycle = true;
  return { dist, negCycle };
}
const V = 5;
const edges = [[0,1,4],[0,2,5],[1,2,-3],[2,3,2],[1,4,7]];
