// Kruskal: sort edges, add if it connects different components (via DSU).
function kruskal(V, edges) {                 // edges: [[u,v,w]]
  const sorted = [...edges].sort((a, b) => a[2] - b[2]);
  const dsu = new DisjointSet(V);
  const mst = [];
  let total = 0;
  for (const [u, v, w] of sorted) {
    if (dsu.find(u) === dsu.find(v)) continue;
    dsu.union(u, v);
    mst.push([u, v, w]);
    total += w;
  }
  return { mst, total, used: mst.length === V - 1 };
}
