// Prim: grow one tree using a min-heap of (weight, vertex).
function prim(V, adj) {                       // adj: Map<v, Map<nbr, w>>
  const inTree = new Set();
  const heap = new Heap((a, b) => a[0] - b[0]);
  heap.push([0, 0]);
  const mst = [];
  let total = 0;
  while (heap.size) {
    const [w, u] = heap.pop();
    if (inTree.has(u)) continue;
    inTree.add(u);
    total += w;
    mst.push([u, w]);
    for (const [v, wt] of adj.get(u) ?? []) if (!inTree.has(v)) heap.push([wt, v]);
  }
  return { mst, total };
}
