function lisWithSequence(nums) {
  if (!nums.length) return { len: 0, seq: [] };
  const tails = [], tailIdx = [], prev = new Array(nums.length).fill(-1);
  for (let i = 0; i < nums.length; i++) {
    const pos = lowerBound(tails.length, k => tails[k] >= nums[i]);
    prev[i] = pos > 0 ? tailIdx[pos - 1] : -1;
    if (pos === tails.length) { tails.push(nums[i]); tailIdx.push(i); }
    else { tails[pos] = nums[i]; tailIdx[pos] = i; }
  }
  const seq = [];
  for (let i = tailIdx[tailIdx.length - 1]; i >= 0; i = prev[i]) seq.unshift(nums[i]);
  return { len: tails.length, seq };
}
