// First index in [0, n) where predicate(i) is true; n if never true.
function lowerBound(n, predicate) {
  let lo = 0, hi = n;
  while (lo < hi) {
    const mid = lo + ((hi - lo) >> 1);
    if (predicate(mid)) hi = mid; else lo = mid + 1;
  }
  return lo;
}
