  if (x < 2) return x;
  let lo = 1, hi = Math.floor(x);
  while (lo <= hi) {
    const mid = lo + ((hi - lo) >> 1);
    const sq = mid * mid;
    if (sq === x) return mid;
    if (sq < x) lo = mid + 1; else hi = mid - 1;
