function closestPair(points) {                 // O(n log n)
  const pts = [...points].sort((a, b) => a[0] - b[0]);
  let best = Infinity;
  const rec = (pts) => {
    if (pts.length <= 3) {
      for (let i = 0; i < pts.length; i++) for (let j = i + 1; j < pts.length; j++) best = Math.min(best, dist(pts[i], pts[j]));
      return pts.sort((a, b) => a[1] - b[1]);
    }
    const mid = pts.length >> 1;
    const midX = pts[mid][0];
    rec(pts.slice(0, mid));
    rec(pts.slice(mid));
    const strip = pts.filter(p => Math.abs(p[0] - midX) < best).sort((a, b) => a[1] - b[1]);
    for (let i = 0; i < strip.length; i++)
      for (let j = i + 1; j < strip.length && strip[j][1] - strip[i][1] < best; j++)
        best = Math.min(best, dist(strip[i], strip[j]));
    return strip;
  };
  const dist = (a, b) => (a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2;
  rec(pts);
  return Math.sqrt(best);
}
