// Skyline via a max-heap with lazy deletion.
function getSkyline(buildings) {          // [left, right, height]
  const events = [];
  for (const [l, r, h] of buildings) { events.push([l, -h, h]); events.push([r, 0, h]); }
  events.sort((a, b) => a[0] - b[0] || a[1] - b[1]);     // opens (negative) before closes
  const heap = new Heap((a, b) => b - a);                // max-heap of heights
  const active = new Map();
  const out = [];
  let i = 0, prev = 0;
  while (i < events.length) {
    const x = events[i][0];
    while (i < events.length && events[i][0] === x) {
      const [, delta, h] = events[i];
      if (delta < 0) { active.set(h, (active.get(h) ?? 0) + 1); heap.push(h); }
      else { const c = (active.get(h) ?? 0) - 1; if (c <= 0) active.delete(h); else active.set(h, c); }
      i++;
    }
    while (heap.size && !active.has(heap.peek())) heap.pop();     // lazy deletion
    const cur = heap.size ? heap.peek() : 0;
    if (cur !== prev) { out.push([x, cur]); prev = cur; }
  }
  return out;
}
console.log(getSkyline([[2,9,10],[3,7,15],[5,12,12],[15,20,10],[19,24,8]]));
