class IntervalTree {
  #root = null;
  constructor(intervals = []) { for (const [s, e] of intervals) this.insert(s, e); }
  insert(start, end) {
    const node = { start, end, maxEnd: end, left: null, right: null };
    this.#root = this.#insertInto(this.#root, node);
    return this;
  }
  #insertInto(root, node) {
    if (!root) return node;
    if (node.start < root.start) root.left = this.#insertInto(root.left, node);
    else root.right = this.#insertInto(root.right, node);
    root.maxEnd = Math.max(root.end, root.left?.maxEnd ?? -Infinity, root.right?.maxEnd ?? -Infinity);
    return root;
  }
  // Find ANY interval containing x, or null. O(log n) on average.
  search(x) {
    let cur = this.#root;
    while (cur) {
      if (x < cur.start) cur = cur.left;
      else if (x > cur.maxEnd) cur = cur.right;         // whole subtree ends after maxEnd >= x
      else if (cur.end >= x) return [cur.start, cur.end];
      else cur = cur.left;                              // covering interval must start left of cur
    }
    return null;
  }
}
const it = new IntervalTree([[6,8],[1,3],[2,5],[10,12]]);
console.log(it.search(7));   // [6,8]
console.log(it.search(4));   // [2,5]
console.log(it.search(11));  // [10,12]
console.log(it.search(20));  // null
