function nextGreater(nums) {                  // next strictly greater, index or -1
  const out = new Array(nums.length).fill(-1);
  const stack = [];
  for (let i = 0; i < nums.length; i++) {
    while (stack.length && nums[stack[stack.length - 1]] < nums[i]) out[stack.pop()] = i;
    stack.push(i);
  }
  return out;
}
function nextGreaterOrEqual(nums) {           // first element >= current
  const out = new Array(nums.length).fill(-1);
  const stack = [];
  for (let i = 0; i < nums.length; i++) {
    while (stack.length && nums[stack[stack.length - 1]] <= nums[i]) out[stack.pop()] = i;
    stack.push(i);
  }
