  const stack = [];
  for (let i = 0; i < nums.length; i++) {
    while (stack.length && nums[stack[stack.length - 1]] <= nums[i]) stack.pop();
    out[i] = stack.length ? stack[stack.length - 1] : -1;
    stack.push(i);
  }
