function hasUndirectedCycle(graph) {
  const visited = new Set();
  const dfs = (u, parent) => {
    visited.add(u);
    for (const v of graph.get(u) ?? []) {
      if (v === parent) continue;         // skip the edge back to parent
      if (visited.has(v)) return true;    // otherwise a genuine cycle
      if (dfs(v, u)) return true;
    }
    return false;
  };
  for (const v of graph.keys()) if (!visited.has(v) && dfs(v, null)) return true;
  return false;
}
