function topoDFS(graph) {
  const WHITE = 0, GRAY = 1, BLACK = 2;
  const color = new Map([...graph.keys()].map(v => [v, WHITE]));
  const order = [];
  let cycle = false;
  const visit = (u) => {
    color.set(u, GRAY);
    for (const v of graph.get(u) ?? []) {
      const c = color.get(v) ?? WHITE;
      if (c === GRAY) { cycle = true; return; }
      if (c === WHITE) visit(v);
    }
    color.set(u, BLACK);
    order.push(u);
  };
  for (const v of color.keys()) if (color.get(v) === WHITE) visit(v);
  if (cycle) return null;
  return order.reverse();
}
