// Recover the path.
function shortestPathDijkstra(graph, source, target) {
  const { dist, prev } = dijkstra(graph, source);
  if (dist.get(target) === Infinity) return null;
  const path = [];
  for (let n = target; n !== undefined; n = prev.get(n)) { path.push(n); if (n === source) break; }
  return { path: path.reverse(), cost: dist.get(target) };
}
