function quickSelect(arr, k) {                 // k is 0-indexed
  const a = [...arr];
  let lo = 0, hi = a.length - 1;
  while (lo < hi) {
    const pivot = a[lo + ((hi - lo) >> 1)];
    let lt = lo, i = lo, gt = hi;
    while (i <= gt) {
      if (a[i] < pivot) { [a[lt], a[i]] = [a[i], a[lt]]; lt++; i++; }
      else if (a[i] > pivot) { [a[i], a[gt]] = [a[gt], a[i]]; gt--; }
      else i++;
    }
    if (k < lt) hi = lt - 1;
    else if (k > gt) lo = gt + 1;
    else return pivot;
  }
  return a[lo];
}
console.log(quickSelect([3,2,1,5,6,4], 2));   // 3
