function maxSumAtLeastK(nums, k) {
  const prefix = [0];
  for (const x of nums) prefix.push(prefix.at(-1) + x);
  const n = nums.length;
  let best = -Infinity;
  const dq = [0];
  for (let r = k; r <= n; r++) {
    while (dq.length && prefix[dq[dq.length - 1]] >= prefix[r - k]) dq.pop();
    dq.push(r - k);
    best = Math.max(best, prefix[r] - prefix[dq[0]]);
  }
  return best;
}
