function maxSumSizeBetween(nums, minLen, maxLen) {
  const prefix = [0];
  for (const x of nums) prefix.push(prefix.at(-1) + x);
  const n = nums.length;
  const dq = [0];
  let best = -Infinity;
  for (let r = 1; r <= n; r++) {
    if (r < minLen) continue;
    while (dq.length && dq[0] < r - maxLen) dq.shift();
    while (dq.length && prefix[dq[dq.length - 1]] >= prefix[r - minLen]) dq.pop();
    dq.push(r - minLen);
    best = Math.max(best, prefix[r] - prefix[dq[0]]);
  }
  return best;
