function spiralGeneric(grid) {
  const R = grid.length, C = grid[0].length;
  const seen = Array.from({ length: R }, () => new Array(C).fill(false));
  const dirs = [[0,1],[1,0],[0,-1],[-1,0]];
  const out = [];
  let r = 0, c = 0, d = 0;
  for (let k = 0; k < R * C; k++) {
    out.push(grid[r][c]);
    seen[r][c] = true;
    const [dr, dc] = dirs[d];
    const nr = r + dr, nc = c + dc;
    if (nr < 0 || nr >= R || nc < 0 || nc >= C || seen[nr][nc]) {
      d = (d + 1) % 4;
      const [dr2, dc2] = dirs[d];
      const nr2 = r + dr2, nc2 = c + dc2;
      if (nr2 < 0 || nr2 >= R || nc2 < 0 || nc2 >= C || seen[nr2][nc2]) break;
      r = nr2; c = nc2;
      continue;
    }
    r = nr; c = nc;
  }
  return out;
}
console.log(spiralGeneric([[1,2,3],[4,5,6],[7,8,9]]));   // [1,2,3,6,9,8,7,4,5]
