function floodFill(image, sr, sc, newColor) {
  if (!image.length || image[sr][sc] === newColor) return image;
  const old = image[sr][sc];
  const stack = [[sr, sc]], dirs = [[-1,0],[1,0],[0,-1],[0,1]];
  while (stack.length) {
    const [r, c] = stack.pop();
    if (r < 0 || r >= image.length || c < 0 || c >= image[0].length) continue;
    if (image[r][c] !== old) continue;
    image[r][c] = newColor;
    for (const [dr, dc] of dirs) stack.push([r + dr, c + dc]);
