function topologicalSort(graph) {            // graph: Map<v, neighborArray>, directed
  const indeg = new Map();
  for (const v of graph.keys()) indeg.set(v, 0);
  for (const v of graph.keys()) for (const w of graph.get(v) ?? []) indeg.set(w, (indeg.get(w) ?? 0) + 1);
  const q = [...indeg].filter(([, d]) => d === 0).map(([v]) => v);
  const order = [];
  const inq = new Map(q.map(v => [v, 0]));   // O(1) queue: a Map with an explicit head
  const queue = [...q];
  let head = 0;
  while (head < queue.length) {
    const u = queue[head++];
    order.push(u);
    for (const v of graph.get(u) ?? []) {
      indeg.set(v, indeg.get(v) - 1);
      if (indeg.get(v) === 0) queue.push(v);
    }
  }
