// Tarjan's SCC (iterative-safe version, returning component ids).
function tarjanSCC(graph) {
  let index = 0;
  const idx = new Map(), low = new Map(), onStack = new Set(), stack = [], comp = new Map();
  let compCount = 0;
  const strongConnect = (v0) => {
    idx.set(v0, index); low.set(v0, index); index++;
    stack.push(v0); onStack.add(v0);
    for (const w of graph.get(v0) ?? []) {
      if (!idx.has(w)) { strongConnect(w); low.set(v0, Math.min(low.get(v0), low.get(w))); }
      else if (onStack.has(w)) low.set(v0, Math.min(low.get(v0), idx.get(w)));
    }
    if (low.get(v0) === idx.get(v0)) {
      for (;;) { const w = stack.pop(); onStack.delete(w); comp.set(w, compCount); if (w === v0) break; }
      compCount++;
    }
  };
  for (const v of graph.keys()) if (!idx.has(v)) strongConnect(v);
  return comp;                                    // Map<vertex, componentId>
}
