    this.#parent = Array.from({ length: n }, (_, i) => i);
    this.#rank = new Array(n).fill(0);
    this.#size = new Array(n).fill(1);
  }
  // With path compression (iterative, to avoid deep recursion).
  find(x) {
    let root = x;
    while (this.#parent[root] !== root) root = this.#parent[root];
    while (this.#parent[x] !== root) { const next = this.#parent[x]; this.#parent[x] = root; x = next; }
    return root;
  }
  union(a, b) {
    const ra = this.find(a), rb = this.find(b);
    if (ra === rb) return false;
    // Union by rank: attach the shorter tree under the taller one.
    if (this.#rank[ra] < this.#rank[rb]) { this.#parent[ra] = rb; }
    else if (this.#rank[ra] > this.#rank[rb]) { this.#parent[rb] = ra; }
    else { this.#parent[rb] = ra; this.#rank[ra]++; }
    return true;
  }
  connected(a, b) { return this.find(a) === this.find(b); }
  get componentCount() { let c = 0; for (let i = 0; i < this.#parent.length; i++) if (this.#parent[i] === i) c++; return c; }
  get size() { return this.#parent.length; }
  #unionImpl(a, b) {
    const ra = this.find(a), rb = this.find(b);
    if (ra === rb) return false;
    if (this.#size[ra] < this.#size[rb]) { this.#parent[ra] = rb; this.#size[rb] += this.#size[ra]; }
    else { this.#parent[rb] = ra; this.#size[ra] += this.#size[rb]; }
    return true;
  }
  unionBySize(a, b) { return this.#unionImpl(a, b); }
}
