// Kruskal with DSU.
function kruskal(V, edges) {
  const dsu = new DisjointSet(V);
  const sorted = [...edges].sort((a, b) => a[2] - b[2]);
  const mst = [];
  let total = 0;
  for (const [u, v, w] of sorted) {
    if (!dsu.union(u, v)) continue;      // would form a cycle
    mst.push([u, v, w]); total += w;
    if (mst.length === V - 1) break;
  }
  return { mst, total, complete: mst.length === V - 1 };
}
