// Accounts merge with DSU.
function accountsMerge(accounts) {
  const parent = new Map();                        // email -> owner index
  const find = (x) => { while (parent.get(x) !== x) { parent.set(x, parent.get(parent.get(x))); x = parent.get(x); } return x; };
  const union = (a, b) => { const ra = find(a), rb = find(b); if (ra !== rb) parent.set(rb, ra); };
  accounts.forEach((acc, i) => acc[1].forEach(email => parent.set(email, email)));
  accounts.forEach((acc) => acc[1].forEach(email => union(email, acc[1][0])));
  const groups = new Map();
  accounts.forEach((acc) => {
    const root = find(acc[1][0]);
    if (!groups.has(root)) groups.set(root, new Set());
    groups.get(root).add(acc[0]);
  });
  return [...groups.values()].map(s => [...s]);
}
