class LRUCache {
  #capacity;
  #map = new Map();     // key -> node
  #head = null;         // most recently used sentinel
  #tail = null;         // least recently used sentinel
  constructor(capacity) {
    if (capacity <= 0) throw new RangeError('capacity must be positive');
    this.#capacity = capacity;
    this.#head = new Node(null, null);
    this.#tail = new Node(null, null);
    this.#head.next = this.#tail;
    this.#tail.prev = this.#head;
  }
  #remove(node) { node.prev.next = node.next; node.next.prev = node.prev; node.prev = node.next = null; }
  #addToFront(node) { node.next = this.#head.next; node.prev = this.#head; this.#head.next.prev = node; this.#head.next = node; }
  get(key) {
    if (!this.#map.has(key)) return -1;
    const node = this.#map.get(key);
    this.#remove(node);
    this.#addToFront(node);
    return node.value;
  }
  put(key, value) {
    if (this.#map.has(key)) {
      const node = this.#map.get(key);
      node.value = value;
      this.#remove(node); this.#addToFront(node);
      return;
    }
    if (this.#map.size >= this.#capacity) {
      const lru = this.#tail.prev;         // the actual LRU node
      this.#remove(lru);
      this.#map.delete(lru.key);
    }
    const node = new Node(key, value);
    this.#map.set(key, node);
    this.#addToFront(node);
  }
  get size() { return this.#map.size; }
  keysLRUtoMRU() { const out = []; for (let n = this.#head.next; n !== this.#tail; n = n.next) out.push(n.key); return out; }
}
