class LFUCache {
  #cap; #counts = new Map(); #values = new Map(); #buckets = new Map(); #min = 0;
  constructor(capacity) { if (capacity <= 0) throw new RangeError('capacity must be positive'); this.#cap = capacity; }
  #bucketFor(c, create = false) {
    if (!this.#buckets.has(c)) { if (!create) return null; const s = new Set(); this.#buckets.set(c, s); return s; }
    return this.#buckets.get(c);
  }
  get(key) {
    if (!this.#values.has(key)) return -1;
    const c = this.#counts.get(key);
    this.#bucketFor(c).delete(key);
    if (c === this.#min && this.#bucketFor(c).size === 0) {
      this.#min++;
      while (this.#min < Infinity && !this.#bucketFor(this.#min)) this.#min++;
    }
    this.#counts.set(key, c + 1);
    this.#bucketFor(c + 1, true).add(key);
    return this.#values.get(key);
  }
  put(key, value) {
    if (this.#values.has(key)) { this.#values.set(key, value); return this.get(key); }
    if (this.#values.size >= this.#cap) {
      const evictKey = this.#bucketFor(this.#min).values().next().value;
      this.#bucketFor(this.#min).delete(evictKey);
      this.#values.delete(evictKey);
      this.#counts.delete(evictKey);
    }
    this.#values.set(key, value);
    this.#counts.set(key, 1);
    this.#bucketFor(1, true).add(key);
    this.#min = 1;
    return this;
  }
  get size() { return this.#values.size; }
}
