class Fenwick {
  #n; #tree;
  constructor(nOrArray) {
    if (Array.isArray(nOrArray)) {
      this.#n = nOrArray.length;
      this.#tree = new Array(this.#n + 1).fill(0);
      nOrArray.forEach((v, i) => this.#update(i + 1, v));   // 1-indexed
    } else {
      this.#n = nOrArray;
      this.#tree = new Array(this.#n + 1).fill(0);
    }
  }
  #update(i, delta) { for (; i <= this.#n; i += i & -i) this.#tree[i] += delta; }
  add(i, delta) { this.#update(i + 1, delta); }             // 0-indexed API
  prefixSum(i) { let s = 0; for (let k = i + 1; k > 0; k -= k & -k) s += this.#tree[k]; return s; }
  rangeSum(l, r) { return this.prefixSum(r) - this.prefixSum(l - 1); }
  get(i) { return this.rangeSum(i, i); }
  // Linear-time build from an array (the constructor path).
  static fromArray(a) { const f = new Fenwick(a.length); for (let i = 0; i < a.length; i++) f.add(i, a[i]); return f; }
}
