class FenwickPublic {
  constructor(n) { this.n = n; this.tree = new Array(n + 1).fill(0); }
  add(i, d) { for (let k = i + 1; k <= this.n; k += k & -k) this.tree[k] += d; }
  prefix(i) { let s = 0; for (let k = i + 1; k > 0; k -= k & -k) s += this.tree[k]; return s; }
  kth(k) {
    let pos = 0;
    let step = 1;
    while (step * 2 <= this.n) step *= 2;
    for (; step > 0; step >>= 1) {
      if (pos + step <= this.n && this.tree[pos + step] < k) { k -= this.tree[pos + step]; pos += step; }
    }
    return pos;                          // 0-indexed value position
  }
}
