class SegmentTree {
  #n; #size; #tree; #op; #identity;
  constructor(arr, op = (a, b) => a + b, identity = 0) {
    this.#n = arr.length;
    this.#op = op; this.#identity = identity;
    this.#size = 1;
    while (this.#size < this.#n) this.#size <<= 1;      // next power of two
    this.#tree = new Array(this.#size * 2).fill(identity);
    arr.forEach((v, i) => { this.#tree[this.#size + i] = v; });
    for (let i = this.#size - 1; i > 0; i--) this.#tree[i] = this.#op(this.#tree[2*i], this.#tree[2*i+1]);
  }
  get length() { return this.#n; }
  pointUpdate(i, value) {
    let p = this.#size + i;
    this.#tree[p] = value;
    for (p >>= 1; p > 0; p >>= 1) this.#tree[p] = this.#op(this.#tree[2*p], this.#tree[2*p+1]);
    return this;
  }
  #rangeQuery(l, r) {                 // [l, r)
    let res = this.#identity;
    for (l += this.#size, r += this.#size; l < r; l >>= 1, r >>= 1) {
      if (l & 1) res = this.#op(this.#op(res, this.#tree[l++]), this.#identity);
      if (r & 1) res = this.#op(this.#op(res, this.#tree[--r]), this.#identity);
    }
    return res;
  }
  query(l, r) { return this.#rangeQuery(l, r); }
  queryRange(l, r) { return this.#rangeQuery(l, r + 1); }
  all() { return this.#tree[1]; }
  // Max over a range (op = max, identity = -Infinity).
  static rangeMax(arr, l, r) {
    const st = new SegmentTree(arr, Math.max, -Infinity);
    return st.queryRange(l, r);
  }
  // Min over a range.
  static rangeMin(arr, l, r) {
    const st = new SegmentTree(arr, Math.min, Infinity);
    return st.queryRange(l, r);
  }
}
