class LazySegmentTree {
  #size; #sum; #lazy;
  constructor(arr) {
    this.#n = arr.length;
    this.#size = 1;
    while (this.#size < this.#n) this.#size <<= 1;
    this.#sum = new Array(this.#size * 2).fill(0);
    this.#lazy = new Array(this.#size * 2).fill(0);
    arr.forEach((v, i) => { this.#sum[this.#size + i] = v; });
    for (let i = this.#size - 1; i > 0; i--) this.#sum[i] = this.#sum[2*i] + this.#sum[2*i+1];
  }
  get root() { return this.#sum[1]; }
  #apply(node, len, delta) { this.#sum[node] += delta * len; this.#lazy[node] += delta; }
  #push(node, l, r) {
    if (this.#lazy[node] === 0 || l === r) return;
    const mid = (l + r) >> 1;
    this.#apply(2*node, mid - l + 1, this.#lazy[node]);
    this.#apply(2*node+1, r - mid, this.#lazy[node]);
    this.#lazy[node] = 0;
  }
  #update(node, l, r, ql, qr, delta) {
    if (qr < l || r < ql) return;
    if (ql <= l && r <= qr) { this.#apply(node, r - l + 1, delta); return; }
    this.#push(node, l, r);
    const mid = (l + r) >> 1;
    this.#update(2*node, l, mid, ql, qr, delta);
    this.#update(2*node+1, mid + 1, r, ql, qr, delta);
    this.#sum[node] = this.#sum[2*node] + this.#sum[2*node+1];
  }
  rangeAdd(l, r, delta) { this.#update(1, 0, this.#size - 1, l, r, delta); return this; }
  #query(node, l, r, ql, qr) {
    if (qr < l || r < ql) return 0;
    if (ql <= l && r <= qr) return this.#sum[node];
    this.#push(node, l, r);
    const mid = (l + r) >> 1;
    return this.#query(2*node, l, mid, ql, qr) + this.#query(2*node+1, mid + 1, r, ql, qr);
  }
  rangeSum(l, r) { return this.#query(1, 0, this.#size - 1, l, r); }
}
