// Bloom filter with k independent hash functions from one base hash (Kirsch-Mitzenmacher).
class BloomFilter {
  #bits; #size; #k; #inserted = 0;
  constructor(expectedItems, falsePositiveRate = 0.01) {
    if (expectedItems <= 0) throw new RangeError('expectedItems must be positive');
    if (falsePositiveRate <= 0 || falsePositiveRate >= 1) throw new RangeError('fpp must be in (0,1)');
    this.#size = Math.ceil(-expectedItems * Math.log(falsePositiveRate) / (Math.log(2) ** 2));
    this.#k = Math.max(1, Math.round((this.#size / expectedItems) * Math.log(2)));
    this.#bits = new Uint8Array(Math.ceil(this.#size / 8));
  }
