// HyperLogLog is available in some engines; here is a compact CardMeter sketch concept.
class DistinctApprox {
  #bits = new Uint8Array(2048);      // 256 registers
  #alpha = 0.7213 / (1 + 1.079 / 256);
  add(str) {
    let h1 = 0x9747b28c, h2 = 0x85ebca6b;
    for (let i = 0; i < str.length; i++) { h1 = Math.imul(h1 ^ str.charCodeAt(i), 0x01000193); h2 = Math.imul(h2 ^ str.charCodeAt(i), 0x85ebca6b); }
    const hash = ((h1 >>> 0) * 4294967296 + (h2 >>> 0)) >>> 0;
    const idx = hash >>> 24 & 0xff;   // leading 8 bits
    const rest = hash & 0xffffff;
    let rank = 1;
    while (rest & (1 << (24 - rank))) rank++;
    if (rank > this.#bits[idx]) this.#bits[idx] = rank;
    return this;
  }
  count() {
    const z = this.#bits.reduce((a, b) => a + 2 ** -b, 0);
    const m = 256;
    const estimate = this.#alpha * m * m / z;
    const smallRange = m * 2.5;
    if (estimate <= smallRange) {
      let V = 0;
      for (const r of this.#bits) if (r === 0) V++;
      return m * Math.log(m / V);
    }
    return estimate;
  }
}
