function quicksort(a, lo = 0, hi = a.length - 1) {
  while (lo < hi) {
    const [lt, gt] = partition3(a, lo, hi);
    if (lt - lo < hi - gt) { quicksort(a, lo, lt - 1); lo = gt + 1; }   // recurse on the smaller side
    else { quicksort(a, gt + 1, hi); hi = lt - 1; }                  // loop on the larger side
  }
  return a;
}
function partition3(a, lo, hi) {
  const pivot = a[lo + ((hi - lo) >> 1)];
  let lt = lo, i = lo, gt = hi;
  while (i <= gt) {
    if (a[i] < pivot) { [a[lt], a[i]] = [a[i], a[lt]]; lt++; i++; }
    else if (a[i] > pivot) { [a[i], a[gt]] = [a[gt], a[i]]; gt--; }    // i does NOT advance
    else i++;
  }
  return [lt, gt];
}
