function bucketSort(arr, bucketCount = 8) {
  if (arr.length === 0) return arr;
  let min = Infinity, max = -Infinity;
  for (const x of arr) { if (x < min) min = x; if (x > max) max = x; }
  const width = (max - min) / bucketCount || 1;
  const buckets = Array.from({ length: bucketCount }, () => []);
  for (const x of arr) {
    let b = Math.floor((x - min) / width);
    if (b >= bucketCount) b = bucketCount - 1;
    buckets[b].push(x);
  }
  const out = [];
  for (const b of buckets) {
    if (b.length <= 32) insertionSortInPlace(b); else b.sort((x, y) => x - y);
    out.push(...b);
  }
  return out;
}
function insertionSortInPlace(a) {
  for (let i = 1; i < a.length; i++) {
    const key = a[i]; let j = i - 1;
    while (j >= 0 && a[j] > key) { a[j + 1] = a[j]; j--; }
    a[j + 1] = key;
  }
  return a;
}
