function radixSortLSD(arr, base = 10) {
  if (arr.length <= 1) return arr.slice();
  let max = -Infinity;
  for (const x of arr) if (x > max) max = x;
  let out = arr.slice();
  for (let exp = 1; Math.floor(max / exp) > 0; exp *= base) {
    const count = new Array(base).fill(0);
    for (const x of out) count[Math.floor(x / exp) % base]++;
    for (let i = 1; i < base; i++) count[i] += count[i - 1];
    const next = new Array(out.length);
    for (let i = out.length - 1; i >= 0; i--) {
      const d = Math.floor(out[i] / exp) % base;
      next[--count[d]] = out[i];
    }
    out = next;
  }
  return out;
}
