function radixSortUint32(arr) {
  if (arr.length <= 1) return arr.slice();
  let src = arr.slice();
  for (let shift = 0; shift < 32; shift += 8) {
    const count = new Uint32Array(256);
    for (let i = 0; i < src.length; i++) count[(src[i] >>> shift) & 0xff]++;
    let sum = 0;
    for (let i = 0; i < 256; i++) { const c = count[i]; count[i] = sum; sum += c; }
    const next = new Array(src.length);
    for (let i = 0; i < src.length; i++) next[count[(src[i] >>> shift) & 0xff]++] = src[i];
    src = next;
  }
  return src;
}
