function aggressiveCows(stalls, cows) {
  stalls = [...stalls].sort((a, b) => a - b);
  const can = (d) => {
    let placed = 1, last = stalls[0];
    for (let i = 1; i < stalls.length; i++) {
      if (stalls[i] - last >= d) { placed++; last = stalls[i]; if (placed >= cows) return true; }
    }
    return placed >= cows;
  };
  let lo = 0, hi = stalls[stalls.length - 1] - stalls[0];
  while (lo < hi) {
    const mid = lo + ((hi - lo + 1) >> 1);       // round UP so the loop terminates
    if (can(mid)) lo = mid; else hi = mid - 1;
  }
  return lo;
}
