function shipWithinDays(weights, days) {
  const can = (cap) => {
    let used = 1, cur = 0;
    for (const w of weights) {
      if (w > cap) return false;
      if (cur + w > cap) { used++; cur = w; if (used > days) return false; }
      else cur += w;
    }
    return true;
  };
