function kthOfTwoSorted(a, b, k) {
  if (a.length + b.length < k) throw new RangeError('k too large');
  if (a.length > b.length) [a, b] = [b, a];
  const m = a.length, n = b.length;
  let lo = Math.max(0, k - n), hi = Math.min(k, m);
  while (lo <= hi) {
    const i = lo + ((hi - lo) >> 1), j = k - i;
    const aLeft = i > 0 ? a[i - 1] : -Infinity, aRight = i < m ? a[i] : Infinity;
    const bLeft = j > 0 ? b[j - 1] : -Infinity, bRight = j < n ? b[j] : Infinity;
    if (aLeft <= bRight && bLeft <= aRight) return Math.max(aLeft, bLeft);
    if (aLeft > bRight) hi = i - 1; else lo = i + 1;
  }
  throw new Error('unreachable');
}
