function findAnagrams(s, t) {
  if (s.length < t.length || t.length === 0) return [];
  const need = new Map(), have = new Map();
  for (const c of t) need.set(c, (need.get(c) ?? 0) + 1);
  let matched = 0;
  const out = [];
  for (let r = 0; r < s.length; r++) {
    const c = s[r];
    have.set(c, (have.get(c) ?? 0) + 1);
    if (have.get(c) === need.get(c)) matched++;
    if (r >= t.length) {
      const outChar = s[r - t.length];
      if (have.get(outChar) === need.get(outChar)) matched--;
      have.set(outChar, have.get(outChar) - 1);
      if (have.get(outChar) === 0) have.delete(outChar);
    }
    if (have.size === need.size && matched === need.size) out.push(r - t.length + 1);
  }
  return out;
}
