function minWindow(s, t) {
  if (s.length < t.length || t.length === 0) return '';
  const need = new Map();
  for (const c of t) need.set(c, (need.get(c) ?? 0) + 1);
  const have = new Map();
  let required = need.size, formed = 0, l = 0;
  let bestLen = Infinity, bestStart = 0;
  for (let r = 0; r < s.length; r++) {
    const c = s[r];
    if (need.has(c)) {
      have.set(c, (have.get(c) ?? 0) + 1);
      if (have.get(c) === need.get(c)) formed++;
    }
    while (formed === required) {
      if (r - l + 1 < bestLen) { bestLen = r - l + 1; bestStart = l; }
      const lc = s[l];
      if (need.has(lc)) { have.set(lc, have.get(lc) - 1); if (have.get(lc) < need.get(lc)) formed--; }
      l++;
    }
  }
  return bestLen === Infinity ? '' : s.slice(bestStart, bestStart + bestLen);
}
console.log(minWindow('ADOBECODEBANC', 'ABC'));   // 'BANC'
console.log(minWindow('a', 'a'));                 // 'a'
