function rangeUpdateDiff(n, updates) {      // updates: [[l, r, delta]], inclusive
  const diff = new Array(n + 1).fill(0);
  for (const [l, r, delta] of updates) { diff[l] += delta; if (r + 1 < n) diff[r + 1] -= delta; }
  const out = new Array(n);
  let cur = 0;
  for (let i = 0; i < n; i++) { cur += diff[i]; out[i] = cur; }
  return out;
