function weightedIntervalSchedule(intervals) {   // [start, end, weight]
  const sorted = [...intervals].sort((a, b) => a[1] - b[1]);
  const n = sorted.length;
  const ends = sorted.map(x => x[1]);
  const dp = new Array(n + 1).fill(0);
  for (let i = 1; i <= n; i++) {
    const j = lowerBound(ends.length, k => ends[k] >= sorted[i - 1][0]);   // last compatible index
    dp[i] = Math.max(dp[i - 1], dp[j] + sorted[i - 1][2]);
  }
  return dp[n];
