function huffman(freqs) {                      // freqs: [[symbol, freq]]
  const heap = new Heap((a, b) => a.freq - b.freq);
  for (const [value, freq] of freqs) heap.push(new HuffmanNode(freq, value));
  while (heap.size > 1) { const a = heap.pop(), b = heap.pop(); heap.push(new HuffmanNode(a.freq + b.freq, null, a, b)); }
  return heap.peek();
}
function huffmanCodes(freqs) {
  const root = huffman(freqs);
  const codes = {};
  const walk = (n, path) => {
    if (n.value !== null) { codes[n.value] = path; return; }
    walk(n.left, path + '0'); walk(n.right, path + '1');
  };
  walk(root, '');
  return codes;
}
