function minRefuelStops(target, tank, stations) {
  const sorted = [...stations].sort((a, b) => a[0] - b[0]);
  let maxReach = tank, stops = 0, i = 0;
  while (maxReach < target) {
    let bestFuel = 0, found = false;
    while (i < sorted.length && sorted[i][0] <= maxReach) { bestFuel = Math.max(bestFuel, sorted[i][1]); found = true; i++; }
