function combinationSum(candidates, target) {
  const sorted = [...candidates].sort((a, b) => a - b);
  const out = [];
  const rec = (start, remaining, path) => {
    if (remaining === 0) { out.push([...path]); return; }
    for (let i = start; i < sorted.length; i++) {
      if (sorted[i] > remaining) break;        // prune: sorted, so all later are bigger too
      path.push(sorted[i]);
      rec(i, remaining - sorted[i], path);     // i, not i+1: reuse allowed
      path.pop();
    }
  };
  rec(0, target, []);
  return out;
}
