function solveSudoku(board) {
  const rows = Array.from({ length: 9 }, () => new Array(10).fill(0));
  const cols = Array.from({ length: 9 }, () => new Array(10).fill(0));
  const boxes = Array.from({ length: 9 }, () => new Array(10).fill(0));
  const empties = [];
  for (let r = 0; r < 9; r++) for (let c = 0; c < 9; c++) {
    const v = board[r][c].charCodeAt(0) - 48;
    if (v === 0) empties.push([r, c]);
    else { rows[r][v] = 1; cols[c][v] = 1; boxes[((r / 3) | 0) * 3 + ((c / 3) | 0)][v] = 1; }
  }
  const rec = (k) => {
    if (k === empties.length) return true;
    const [r, c] = empties[k];
    const b = ((r / 3) | 0) * 3 + ((c / 3) | 0);
    for (let v = 1; v <= 9; v++) {
      if (rows[r][v] || cols[c][v] || boxes[b][v]) continue;
      rows[r][v] = cols[c][v] = boxes[b][v] = 1;
      board[r][c] = String(v);
      if (rec(k + 1)) return true;                // success: do not undo
      board[r][c] = '.';
      rows[r][v] = cols[c][v] = boxes[b][v] = 0;  // undo
    }
    return false;
  };
  return rec(0) ? board : null;
}
