function exist(board, word) {
  if (!board.length || !board[0].length) return false;
  const R = board.length, C = board[0].length;
  if (word.length > R * C) return false;
  const rec = (r, c, k) => {
    if (r < 0 || r >= R || c < 0 || c >= C) return false;
    if (board[r][c] !== word[k]) return false;
    if (k === word.length - 1) return true;
    const ch = board[r][c];
    board[r][c] = '\0';                       // mark visited (no extra space)
    const found = rec(r+1,c,k+1) || rec(r-1,c,k+1) || rec(r,c+1,k+1) || rec(r,c-1,k+1);
    board[r][c] = ch;                          // undo
    return found;
  };
  for (let r = 0; r < R; r++) for (let c = 0; c < C; c++) if (rec(r, c, 0)) return true;
  return false;
}
const bw = [['A','B','C','E'],['S','F','C','S'],['A','D','E','E']];
console.log(exist(bw, 'ABCCED'));   // true
console.log(exist(bw, 'SEE'));      // true
console.log(exist(bw, 'ABCB'));     // false
