// Duplicate skipping: subsets with unique values only.
function subsetsUnique(nums) {
  const sorted = [...nums].sort((a, b) => a - b);
  const out = [];
  const rec = (start, path) => {
    out.push([...path]);
    for (let i = start; i < sorted.length; i++) {
      if (i > start && sorted[i] === sorted[i - 1]) continue;   // skip duplicates
      path.push(sorted[i]); rec(i + 1, path); path.pop();
    }
  };
  rec(0, []);
  return out;
}
