function canMakeWord(word, dict) {
  const trie = new Trie();
  for (const w of dict) trie.insert(w);
  const R = word.length;
  const memo = Array.from({ length: R + 1 }, () => new Array(R + 1).fill(null));
  const rec = (i, j) => {                      // can word[i..j) be built from the trie?
    if (j <= i) return true;
    if (memo[i][j] !== null) return memo[i][j];
    let node = trie.rootRef;
    for (let k = i; k < j; k++) {
      node = node.children.get(word[k]);
      if (!node) { memo[i][j] = false; return false; }
      if (node.isWord && rec(k + 1, j)) { memo[i][j] = true; return true; }
    }
    memo[i][j] = false;
    return false;
  };
  return rec(0, R);
}
console.log(canMakeWord('leetcode', ['leet','code']));   // true
console.log(canMakeWord('leetcodes', ['leet','code']));  // false
