// Unbounded (complete) knapsack: iterate capacity FORWARD.
function knapsackUnbounded(weights, values, W) {
  const dp = new Array(W + 1).fill(0);
  for (let c = 1; c <= W; c++)
    for (let i = 0; i < weights.length; i++)
      if (weights[i] <= c) dp[c] = Math.max(dp[c], dp[c - weights[i]] + values[i]);
  return dp[W];
}
