function lisBinary(nums) {
  const tails = [];                 // tails[k] = smallest tail of an increasing subsequence of length k+1
  for (const x of nums) {
    const i = lowerBound(tails.length, k => tails[k] >= x);
    if (i === tails.length) tails.push(x); else tails[i] = x;
  }
  return tails.length;
}
console.log(lisBinary([10,9,2,5,3,7,101,18]));   // 4
console.log(lisBinary([7,7,7,7,7]));              // 1
console.log(lisBinary([]));                      // 0
