function lcs(a, b) {
  const R = a.length, C = b.length;
  const dp = Array.from({ length: R + 1 }, () => new Array(C + 1).fill(0));
  for (let i = 1; i <= R; i++) for (let j = 1; j <= C; j++)
    dp[i][j] = a[i-1] === b[j-1] ? dp[i-1][j-1] + 1 : Math.max(dp[i-1][j], dp[i][j-1]);
  return dp[R][C];
}
