function editDistance(a, b) {
  const R = a.length, C = b.length;
  let prev = Array.from({ length: C + 1 }, (_, j) => j);
  let cur = new Array(C + 1).fill(0);
  for (let i = 1; i <= R; i++) {
    cur[0] = i;
    for (let j = 1; j <= C; j++) {
      cur[j] = a[i-1] === b[j-1] ? prev[j-1] : 1 + Math.min(prev[j], cur[j-1], prev[j-1]);
    }
    [prev, cur] = [cur, prev];
  }
  return prev[C];
}
