// Rolling 2 rows with a saved diagonal (the 1D edit distance).
function editDistance1D(a, b) {
  const C = b.length;
  const dp = Array.from({ length: C + 1 }, (_, j) => j);
  for (let i = 1; i <= a.length; i++) {
    let diag = dp[0];
    dp[0] = i;
    for (let j = 1; j <= C; j++) {
      const temp = dp[j];
      dp[j] = a[i-1] === b[j-1] ? diag : 1 + Math.min(dp[j], dp[j-1], diag);
      diag = temp;
    }
  }
  return dp[C];
}
