// Count combinations (coin-outer loop) vs. permutations (sum-outer loop).
function countCombos(coins, target) {
  const dp = new Array(target + 1).fill(0);
  dp[0] = 1;
  for (const c of coins) for (let s = c; s <= target; s++) dp[s] += dp[s - c];
  return dp[target];
}
function countPerms(coins, target) {
  const dp = new Array(target + 1).fill(0);
  dp[0] = 1;
  for (let s = 1; s <= target; s++) for (const c of coins) if (c <= s) dp[s] += dp[s - c];
  return dp[target];
}
