function uniquePathsWithObstacles(m) {      // 1 = obstacle
  const R = m.length, C = m[0].length;
  if (m[0][0] === 1) return 0;
  const dp = new Array(C).fill(1);
  dp[0] = 1;
  for (let r = 1; r < R; r++) for (let c = 0; c < C; c++) {
    if (m[r][c] === 1) dp[c] = 0; else dp[c] += dp[c - 1];
  }
  return dp[C - 1];
}
