// Maximum sum path in a rectangle with moves right/down (and no negatives).
function maxPathGrid(grid) {
  const R = grid.length, C = grid[0].length;
  if (!R || !C) return 0;
  const dp = grid[0].slice();
  for (let c = 1; c < C; c++) dp[c] += dp[c - 1];
  for (let r = 1; r < R; r++) { dp[0] += grid[r][0];
    for (let c = 1; c < C; c++) dp[c] = grid[r][c] + Math.max(dp[c], dp[c - 1]); }
  return dp[C - 1];
}
