function minCutStickAllCuts(length, cuts) {   // ALL given cuts must be made
  const c = [0, ...[...cuts].sort((a, b) => a - b), length];
  const n = c.length;
  const dp = Array.from({ length: n }, () => new Array(n).fill(0));
  for (let len = 2; len < n; len++)
    for (let i = 0; i + len < n; i++) {
      const j = i + len;
      dp[i][j] = Infinity;
      for (let k = i + 1; k < j; k++) dp[i][j] = Math.min(dp[i][j], dp[i][k] + dp[k][j] + c[j] - c[i]);
    }
  return dp[0][n - 1];
}
