function minCutStickOptional(length, cuts) {
  const c = [0, ...[...cuts].sort((a, b) => a - b), length];
  const n = c.length;
  const dp = Array.from({ length: n }, () => new Array(n).fill(0));
  for (let len = 2; len < n; len++)
    for (let i = 0; i + len < n; i++) {
      const j = i + len;
      let best = c[j] - c[i];                              // no interior cut
      for (let k = i + 1; k < j; k++) best = Math.min(best, dp[i][k] + dp[k][j] + c[j] - c[i]);
      dp[i][j] = best;
    }
  return dp[0][n - 1];
}
