function minCostMergeStones(stones) {         // K = 2
  const n = stones.length;
  if (n === 0) return 0;
  const prefix = [0];
  for (const s of stones) prefix.push(prefix.at(-1) + s);
  const dp = Array.from({ length: n }, () => new Array(n).fill(0));
  for (let len = 2; len <= n; len++)
    for (let i = 0; i + len <= n; i++) {
      const j = i + len - 1;
      dp[i][j] = Infinity;
      for (let k = i; k < j; k++)
        dp[i][j] = Math.min(dp[i][j], dp[i][k] + dp[k+1][j] + prefix[j+1] - prefix[i]);
    }
  return dp[0][n-1];
}
