function palindromePartition(s) {           // min cuts
  const n = s.length;
  if (n === 0) return 0;
  const isPal = Array.from({ length: n }, () => new Array(n).fill(false));
  for (let i = n - 1; i >= 0; i--)
    for (let j = i; j < n; j++)
      isPal[i][j] = s[i] === s[j] && (j - i < 2 || isPal[i+1][j-1]);
  const dp = new Array(n).fill(Infinity);
  dp[0] = 0;
  for (let i = 1; i <= n; i++)
    for (let j = 0; j < i; j++) if (isPal[j][i-1]) dp[i] = Math.min(dp[i], dp[j] + 1);
  return dp[n] - 1;
}
console.log(palindromePartition('aab'));          // 1  ("aa"|"b")
console.log(palindromePartition('a'));            // 0
console.log(palindromePartition('abc'));          // 2
