```js
function tspDP(points) {
  const n = points.length;
  if (n === 0) return 0;
  const dist = Array.from({ length: n }, (_, i) => Array.from({ length: n }, (_, j) =>
    i === j ? 0 : Math.hypot(points[i][0] - points[j][0], points[i][1] - points[j][1])));
  const FULL = 1 << n;
  const dp = Array.from({ length: FULL }, () => new Array(n).fill(Infinity));
  for (let i = 1; i < n; i++) dp[1 << i][i] = dist[0][i];
  for (let mask = 1; mask < FULL; mask++) {
    if (!(mask & 1)) continue;                          // must include the start node 0
    for (let i = 1; i < n; i++) {
      if (!(mask & (1 << i))) continue;
      for (let j = 1; j < n; j++) {
        if (mask & (1 << j)) continue;
        const nm = mask | (1 << j);
        dp[nm][j] = Math.min(dp[nm][j], dp[mask][i] + dist[i][j]);
      }
    }
  }
  let best = Infinity;
  for (let i = 1; i < n; i++) best = Math.min(best, dp[FULL - 1][i] + dist[i][0]);
  return best;
}
console.log(tspDP([[0,0],[2,0],[0,2],[1,1]]));   // 4.82842712474619
```

