console.log(mergeClosedIntervals([[1,4],[4,5]]));            // [[1,5]]       closed: merged
console.log(mergeIntervals([[1,4],[2,3]]));                  // [[1,4]]
console.log(mergeIntervals([[5,6],[1,2]]));                  // [[1,2],[5,6]]
