function insertInterval(intervals, newInt) {
  const out = [];
  let i = 0; const n = intervals.length;
  while (i < n && intervals[i][1] < newInt[0]) out.push(intervals[i++]);          // entirely before
  while (i < n && intervals[i][0] <= newInt[1]) {                                 // overlapping
    newInt = [Math.min(newInt[0], intervals[i][0]), Math.max(newInt[1], intervals[i][1])];
    i++;
  }
  out.push(newInt);
  while (i < n) out.push(intervals[i++]);                                          // entirely after
  return out;
}
