function allocateRooms(intervals) {
  const sorted = [...intervals].sort((a, b) => a[0] - b[0]);
  const heap = new Heap((a, b) => a[0] - b[0]);           // min-heap by end time
  const rooms = [[]];
  heap.push([0, 0]);                                       // [endTime, roomIndex]
  for (const [s, e] of sorted) {
    const [earliestEnd, roomIdx] = heap.peek();
    if (s >= earliestEnd) { heap.pop(); heap.push([e, roomIdx]); rooms[roomIdx].push([s, e]); }
    else { const idx = rooms.length; rooms.push([[s, e]]); heap.push([e, idx]); }
  }
  return rooms;
}
