function nextGreater(nums) {                  // next strictly greater, index or -1
  const out = new Array(nums.length).fill(-1);
  const stack = [];
  for (let i = 0; i < nums.length; i++) {
    while (stack.length && nums[stack[stack.length - 1]] < nums[i]) out[stack.pop()] = i;
    stack.push(i);
  }
  return out;
}
function nextGreaterOrEqual(nums) {           // first element >= current
  const out = new Array(nums.length).fill(-1);
  const stack = [];
  for (let i = 0; i < nums.length; i++) {
    while (stack.length && nums[stack[stack.length - 1]] <= nums[i]) out[stack.pop()] = i;
    stack.push(i);
  }
  return out;
}
function previousGreater(nums) {
  const out = new Array(nums.length).fill(-1);
  const stack = [];
  for (let i = 0; i < nums.length; i++) {
    while (stack.length && nums[stack[stack.length - 1]] <= nums[i]) stack.pop();
    out[i] = stack.length ? stack[stack.length - 1] : -1;
    stack.push(i);
  }
  return out;
}
console.log(nextGreater([2,1,5,6,2,3]));        // [2,-1,3,-1,5,-1]
console.log(nextGreaterOrEqual([2,2,3]));       // [1,2,-1]
console.log(previousGreater([2,1,5,6,2,3]));    // [-1,0,-1,-1,3,-1]
