function removeDuplicateLetters(s) {
  const last = new Map();
  for (let i = 0; i < s.length; i++) last.set(s[i], i);
  const inStack = new Set(), stack = [];
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (inStack.has(c)) continue;
    while (stack.length && stack[stack.length - 1] > c && last.get(stack[stack.length - 1]) > i) inStack.delete(stack.pop());
    stack.push(c); inStack.add(c);
  }
  return stack.join('');
}
