function topKLargest(nums, k) {                 // descending output
  if (k <= 0) return [];
  const heap = new Heap((a, b) => a - b);      // min-heap of size k
  for (const x of nums) {
    if (heap.size < k) heap.push(x);
    else if (x > heap.peek()) { heap.pop(); heap.push(x); }
  }
  const out = [];
  while (heap.size) out.push(heap.pop());
  return out;
}
function topKSmallest(nums, k) {                // ascending output
  if (k <= 0) return [];
  const heap = new Heap((a, b) => b - a);      // max-heap of size k
  for (const x of nums) {
    if (heap.size < k) heap.push(x);
    else if (x < heap.peek()) { heap.pop(); heap.push(x); }
  }
  const out = [];
  while (heap.size) out.push(heap.pop());
  return out.reverse();
}
