  const prefix = new Array(n + 1).fill(1), suffix = new Array(n + 1).fill(1);
  for (let i = 0; i < n; i++) prefix[i + 1] = prefix[i] * nums[i];
  for (let i = n - 1; i >= 0; i--) suffix[i] = suffix[i + 1] * nums[i];
