function searchRotatedMatrix(matrix, target) {
  const R = matrix.length;
  if (!R || !matrix[0].length) return false;
  const C = matrix[0].length;
  let lo = 0, hi = R * C - 1;
  while (lo <= hi) {
    const mid = lo + ((hi - lo) >> 1);
    const v = matrix[mid >> 1][mid & 1];                 // flat index -> (row, col)
    if (v === target) return true;
    if (matrix[0][mid & 1] <= v) {                        // the left part of this row is sorted
      if (matrix[0][mid & 1] <= target && target < v) hi = mid - 1; else lo = mid + 1;
    } else {                                              // the right part is sorted
      if (v < target && target <= matrix[mid >> 1][C - 1]) lo = mid + 1; else hi = mid - 1;
    }
  }
  return false;
}
console.log(searchRotatedMatrix([[1,3,5,7],[10,11,16,20],[23,30,34,60]], 16));   // true
console.log(searchRotatedMatrix([[1,3,5,7],[10,11,16,20],[23,30,34,60]], 13));   // false
console.log(searchRotatedMatrix([[1]], 1));   // true
console.log(searchRotatedMatrix([], 1));      // false
