function searchYoungTableau(m, target) {     // rows ascending, columns ascending
  let r = 0, c = m[0].length - 1;
  while (r < m.length && c >= 0) {
    const v = m[r][c];
    if (v === target) return true;
    if (v > target) c--; else r++;
  }
  return false;
}
