function buildLPS(pattern) {                 // longest proper prefix that is also a suffix
  const lps = new Array(pattern.length).fill(0);
  let len = 0;
  for (let i = 1; i < pattern.length; i++) {
    while (len > 0 && pattern[i] !== pattern[len]) len = lps[len - 1];
    if (pattern[i] === pattern[len]) lps[i] = ++len;
  }
  return lps;
}
function kmpSearch(text, pattern) {           // first index or -1
  if (pattern.length === 0) return 0;
  const lps = buildLPS(pattern);
  let j = 0;
  for (let i = 0; i < text.length; i++) {
    while (j > 0 && text[i] !== pattern[j]) j = lps[j - 1];
    if (text[i] === pattern[j]) j++;
    if (j === pattern.length) return i - pattern.length + 1;
  }
  return -1;
}
console.log(kmpSearch('aabaacaa', 'aacaa'));   // 3
console.log(kmpSearch('abcdef', 'def'));       // 3
console.log(kmpSearch('abcdef', 'gh'));       // -1
console.log(buildLPS('aabaacaa'));             // [0,1,0,1,2,0,0,1]
