function rollingHashes(s, L, base = 31, mod = 1_000_000_007) {
  const n = s.length;
  if (L > n) return [];
  let h = 0;
  for (let i = 0; i < L; i++) h = (h * base + s.charCodeAt(i)) % mod;
  let bp = 1;
  for (let i = 1; i < L; i++) bp = (bp * base) % mod;      // base^(L-1) mod mod
  const out = [h];
  for (let i = L; i < n; i++) {
    h = (h * base + s.charCodeAt(i) - s.charCodeAt(i - L) * bp) % mod;
    out.push((h + mod) % mod);
  }
  return out;
}
console.log(rollingHashes('abcdabc', 4).length);   // 4
