function groupAnagramsFast(words) {           // O(26n) instead of O(n log n)
  const groups = new Map();
  for (const w of words) {
    const count = new Array(26).fill(0);
    for (const ch of w.toLowerCase()) count[ch.charCodeAt(0) - 97]++;
