function groupShiftedStrings(strs) {
  const groups = new Map();
  for (const s of strs) {
    const map = new Map();
    let key = '';
    for (const ch of s) {
      if (!map.has(ch)) map.set(ch, String.fromCharCode(97 + map.size));
      key += map.get(ch);
    }
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(s);
  }
  return [...groups.values()];
}
console.log(groupShiftedStrings(['ab','cd','xy','zz']));   // [['ab','cd','xy'],['zz']]
