function isPalindrome(s) {
  let l = 0, r = s.length - 1;
  while (l < r) { if (s[l] !== s[r]) return false; l++; r--; }
  return true;
}
function longestPalindromicSubstring(s) {         // expand around the center, O(n^2), O(1) space
  let best = '', bestLen = 0;
  const expand = (l, r) => {
    while (l >= 0 && r < s.length && s[l] === s[r]) {
      if (r - l + 1 > bestLen) { bestLen = r - l + 1; best = s.slice(l, r + 1); }
      l--; r++;
    }
  };
  for (let i = 0; i < s.length; i++) { expand(i, i); expand(i, i + 1); }
  return best;
}
console.log(isPalindrome('racecar'));                   // true
console.log(longestPalindromicSubstring('babad'));       // 'bab'
console.log(longestPalindromicSubstring('cbbd'));        // 'bb'
