function findAnagramIndexes(s, pattern) {
  const need = new Map();
  for (const c of pattern) need.set(c, (need.get(c) ?? 0) + 1);
  const have = new Map();
  let matched = 0; const out = [];
  for (let r = 0; r < s.length; r++) {
    have.set(s[r], (have.get(s[r]) ?? 0) + 1);
    if (have.get(s[r]) === need.get(s[r])) matched++;
    if (r >= pattern.length) {
      const c = s[r - pattern.length];
      if (have.get(c) === need.get(c)) matched--;
      have.set(c, have.get(c) - 1);
      if (have.get(c) === 0) have.delete(c);
    }
    if (have.size === need.size && matched === need.size) out.push(r - pattern.length + 1);
  }
  return out;
}
console.log(findAnagramIndexes('cbaebabacd', 'abc'));   // [0, 6]
console.log(findAnagramIndexes('abab', 'ab'));          // [0, 1, 2]
console.log(findAnagramIndexes('a', 'ab'));             // []
