```js
function buildAhoCorasick(patterns) {
  const root = new Map();
  const fail = new Map();
  const output = new Map();
  for (const p of patterns) {
    let n = root;
    for (const ch of p) { if (!n.has(ch)) n.set(ch, new Map()); n = n.get(ch); }
    n.set('$', p);
  }
  const q = [];
  for (const child of root.values()) { fail.set(child, root); output.set(child, child.get('$') ? [child.get('$')] : []); q.push(child); }
  while (q.length) {
    const r = q.shift();
    for (const [ch, child] of r) {
      if (ch === '$') continue;
      let f = fail.get(r);
      while (f && !f.has(ch)) f = fail.get(f);
      const target = f && f.has(ch) ? f.get(ch) : root;
      fail.set(child, target);
      output.set(child, [...(output.get(target) ?? []), ...(child.get('$') ? [child.get('$')] : [])]);
      q.push(child);
    }
  }
  return { root, fail, output };
}
function acSearch(patterns, text) {
  const { root, fail, output } = buildAhoCorasick(patterns);
  const out = [];
  let n = root;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    while (n !== root && !n.has(ch)) n = fail.get(n);
    n = n.get(ch) ?? root;
    for (const p of output.get(n) ?? []) out.push({ pattern: p, index: i - p.length + 1 });
  }
  return out;
}
console.log(acSearch(['he','she','his','hers'], 'ushers'));
// [ {pattern:'she',index:1}, {pattern:'he',index:2}, {pattern:'hers',index:2} ]
```

