function reservoirSample(stream, k, rng = Math.random) {
  const reservoir = [];
  for (const item of stream) {
    if (reservoir.length < k) { reservoir.push(item); continue; }
    const j = Math.floor(rng() * (reservoir.length + 1));   // uniform in [0, n]
    if (j < k) reservoir[j] = item;
  }
  return reservoir;
}
console.log(reservoirSample([1,2,3,4,5,6,7,8], 3).length);   // 3
