```js
function weightedReservoir(stream, k, rng = Math.random) {
  const res = [];
  let W = 0;
  for (const item of stream) {
    const w = item.weight;
    if (w <= 0) continue;
    W += w;
    if (res.length < k) { res.push(item); continue; }
    const r = rng() * W;
    if (r < w) res[Math.floor(rng() * k)] = item;       // evict a uniformly random slot
  }
  return res;
}
console.log(weightedReservoir([{ weight: 1, id: 'a' }, { weight: 5, id: 'b' }, { weight: 2, id: 'c' }], 1).length);   // 1
