```js
function aRes(stream, k) {
  const heap = new Heap((a, b) => a.w - b.w);      // min-heap by weight, size k
  for (const item of stream) {
    if (heap.size < k) heap.push(item);
    else if (item.w > heap.peek().w) { heap.pop(); heap.push(item); }
  }
  return heap.size ? heap.toArray() : [];
}
