```js
function misraGries(stream, k) {
  const counters = new Map();
  let total = 0;
  for (const item of stream) {
    total++;
    if (counters.has(item)) { counters.set(item, counters.get(item) + 1); continue; }
    if (counters.size < k - 1) { counters.set(item, 1); continue; }
    for (const [key, c] of [...counters]) { if (c === 1) counters.delete(key); else counters.set(key, c - 1); }
  }
  return { candidates: [...counters.keys()], total, threshold: total / k };
}
console.log(misraGries(['a','b','a','c','a','b','a','d'], 3));   // { candidates: ['a'], total: 8, threshold: 2.666... }
```

