function exactHeavyHitters(streamFactory, k) {
  const { candidates } = misraGries([...streamFactory()], k);
  const counts = new Map(candidates.map(c => [c, 0]));
  for (const item of streamFactory()) if (counts.has(item)) counts.set(item, counts.get(item) + 1);
  return [...counts.entries()].sort((a, b) => b[1] - a[1]).slice(0, k);
}
const makeStream = () => ['a','b','a','c','a','b','a','d'];
console.log(exactHeavyHitters(makeStream, 2));   // [['a',4],['b',2]]
