```js
function spaceSaving(stream, k) {
  const table = new Map();
  let err = 0;
  for (const item of stream) {
    if (table.has(item)) { table.set(item, table.get(item) + 1); continue; }
    if (table.size < k) { table.set(item, 1); continue; }
    let minKey = null, minVal = Infinity;
    for (const [key, v] of table) if (v < minVal) { minVal = v; minKey = key; }
    table.delete(minKey);
    err = minVal;
    table.set(item, minVal + 1);
  }
  return { estimates: [...table.entries()], errorBound: err };
}
console.log(spaceSaving(['a','b','a','c','a','b','a','d'], 3));
// { estimates: [['a',4],['b',2],['d',2]], errorBound: 1 }
