class CountMinSketch {
  constructor(width, depth = 4) {
    this.width = width; this.depth = depth;
    this.table = Array.from({ length: depth }, () => new Float64Array(width));
  }
  hash(row, key) {
    let h = Math.imul(row + 1, 0x9e3779b1);
    for (let i = 0; i < key.length; i++) h = Math.imul(h ^ key.charCodeAt(i), 0x01000193);
    return (h >>> 0) % this.width;
  }
  add(key, count = 1) {
    for (let r = 0; r < this.depth; r++) this.table[r][this.hash(r, key)] += count;
    return this;
  }
  estimate(key) {
    let min = Infinity;
    for (let r = 0; r < this.depth; r++) min = Math.min(min, this.table[r][this.hash(r, key)]);
    return min;
  }
}
const cms = new CountMinSketch(64, 4);
for (let i = 0; i < 10; i++) cms.add('apple');
for (let i = 0; i < 5; i++) cms.add('banana');
console.log(cms.estimate('apple'));    // 10
console.log(cms.estimate('banana'));   // 5
console.log(cms.estimate('cherry'));   // 0
