```js
class DecayingCountMinSketch {
  constructor(width, depth = 4, decayPerMinute = 0.5, clock = () => Date.now()) {
    this.cms = new CountMinSketch(width, depth);
    this.decay = decayPerMinute; this.clock = clock; this.last = clock();
  }
  maybeDecay(now) {
    const minutes = (now - this.last) / 60000;
    if (minutes <= 0) return;
    const f = Math.pow(this.decay, minutes);
    for (let r = 0; r < this.cms.depth; r++) for (let c = 0; c < this.cms.width; c++) this.cms.table[r][c] *= f;
    this.last = now;
  }
  add(key, count = 1) { const now = this.clock(); this.maybeDecay(now); this.cms.add(key, count); return this; }
  estimate(key) { this.maybeDecay(this.clock()); return this.cms.estimate(key); }
}
