function topHeavyHitters(stream, k, width, depth) {
  const cms = new CountMinSketch(width, depth);
  const items = new Set();
  for (const item of stream) { cms.add(item); items.add(item); }
  const heap = new Heap((a, b) => a[1] - b[1]);
  for (const item of items) {
    const est = cms.estimate(item);
    if (heap.size < k) heap.push([item, est]);
    else if (est > heap.peek()[1]) { heap.pop(); heap.push([item, est]); }
  }
  return heap.size ? heap.toArray() : [];
}
