```js
class HyperLogLog {
  constructor(precision = 12) {          // 2^12 = 4096 registers, ~0.81% error
    this.precision = precision;
    this.registers = new Uint8Array(1 << precision);
  }
  #hash(str) {
    let h1 = 0x811c9dc5, h2 = 0x01000193;
    for (let i = 0; i < str.length; i++) { h1 = Math.imul(h1 ^ str.charCodeAt(i), 0x01000193); h2 = Math.imul(h2 ^ str.charCodeAt(i), 0x85ebca6b); }
    return ((h1 >>> 0) * 4294967296 + (h2 >>> 0)) >>> 0;
  }
  add(str) {
    const hash = this.#hash(str);
    const idx = hash >>> (32 - this.precision);
    const rest = hash & ((1 << (32 - this.precision)) - 1);
    let rank = 1;
    while (rest & (1 << (31 - this.precision - rank))) rank++;
    if (rank > this.registers[idx]) this.registers[idx] = rank;
    return this;
  }
  count() {
    const m = this.registers.length;
    const alpha = 0.7213 / (1 + 1.079 / m);
    const invSum = this.registers.reduce((a, r) => a + 2 ** -r, 0);
    let estimate = alpha * m * m / invSum;
    const zeros = this.registers.reduce((a, r) => a + (r === 0 ? 1 : 0), 0);
    if (estimate <= 2.5 * m && zeros > 0) estimate = m * Math.log(m / zeros);
    return estimate;
  }
  merge(other) {
    for (let i = 0; i < this.registers.length; i++) this.registers[i] = Math.max(this.registers[i], other.registers[i]);
    return this;
  }
}
const hll = new HyperLogLog(12);
for (let i = 0; i < 10000; i++) hll.add('user' + i);
console.log(Math.round(hll.count()));   // ~10000
```

