// Per-column heavy hitters in a matrix stream (Misra–Gries + verification).
function columnHeavyHitters(matrix, k) {
  const cols = matrix[0].length;
  const out = [];
  for (let c = 0; c < cols; c++) {
    const colStream = matrix.map(r => r[c]);
    const { candidates } = misraGries(colStream, k);
    const counts = new Map(candidates.map(x => [x, 0]));
    for (const v of colStream) if (counts.has(v)) counts.set(v, counts.get(v) + 1);
    out.push([...counts.entries()].sort((a, b) => b[1] - a[1]).map(e => e[0]));
  }
  return out;
}
console.log(columnHeavyHitters([['a','x'],['b','y'],['a','x'],['c','y']], 2));
// [['a'],['x','y']]
